,"investor":"Apax Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":1000000000.0,"currency":"GBP","amount_basis":"enterprise_value","valuation":null,"valuation_currency":null,"headline":"Funds advised by Apax Partners announce the successful completion of the acquisition of a majority shareholding in Travelex","summary":"Apax funds closed their acquisition of a controlling majority stake in Travelex at an enterprise value the release puts at more than £1bn (agreement announced 28 February 2005).","source_name":"Apax","source_url":"https://www.apax.com/news-views/funds-advised-by-apax-partners-announce-the-successful-completion-of-the-acquisition-of-a-majority-shareholding-in-travelex/","evidence":"The transaction values the company at an enterprise value of more than £1bn.","verified":true},{"key":"pr:0d01a49c58f566c9686f61ddfcef33b2","date":"2005-04-04","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"TIM Hellas Telecommunications S.A.","portco_name":"TIM Hellas Telecommunications","target_website":null,"investor":"Apax Partners' Funds","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":["Texas Pacific Group"],"seller":"TIM International","round":null,"stake_pct":80.87,"amount":1114100000.0,"currency":"EUR","amount_basis":"stake_price","valuation":null,"valuation_currency":null,"headline":"Apax Partners’ Funds and Texas Pacific group to acquire control of Tim Hellas Telecommunications S.A. in a 1.1 billion Euro transaction","summary":"An acquisition company owned by funds advised by Apax Partners and Texas Pacific Group agreed to buy TIM International's 80.87% stake in Greek mobile operator TIM Hellas for €1,114.1 million.","source_name":"Apax","source_url":"https://www.apax.com/news-views/apax-partners-funds-and-texas-pacific-group-to-acquire-control-of-tim-hellas-telecommunications-sa-in-a-11-billion-euro-transaction/","evidence":"An acquisition company owned by private equity funds advised by Texas Pacific Group and Apax Partners signed a conditional acquisition agreement today with TIM International for the acquisition of its 80.87% shareholding in TIM Hellas Telecommunications S.A, the Greek wireless operator. The purchase price for TIM's shareholding in TIM Hellas is €1,114.1 million, equivalent to approximately €16.43 per share, representing a premium of 17.6% to TIM Hellas' six month average ADR price based on the current exchange rate.","verified":true},{"key":"pr:6304632820d5753108871c1053c11fcc","date":"2005-04-21","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"Mölnlycke Health Care","portco_name":"Mölnlycke Health Care","target_website":"molnlycke.com","investor":"Apax Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":"Nordic Capital","round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Nordic Capital to sell Mölnlycke Health Care to Apax Partners Funds","summary":"Nordic Capital and other major shareholders agreed to sell surgical and wound care maker Mölnlycke Health Care to funds advised by Apax Partners; no price was disclosed.","source_name":"Apax","source_url":"https://www.apax.com/news-views/nordic-capital-to-sell-molnlycke-health-care-to-apax-partners-funds/","evidence":"Nordic Capital and other major shareholders have entered into a definitive agreement to sell Mölnlycke Health Care to funds advised by Apax Partners.","verified":null},{"key":"pr:15cb8659d930da2b08d650a1ffe99fd3","date":"2005-05-26","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"HIT Entertainment","portco_name":"HIT Entertainment","target_website":null,"investor":"Sunshine Acquisition Limited (Funds advised by Apax Partners)","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":