res represented approximately 11.9% of the group's share capital.","verified":null},{"key":"pr:e34fe84a201d4d556462b536a6e55486","date":"2005-07-18","date_text":null,"kind":"funding_round","asset_class":"venture_capital","target":"Xanodyne Pharmaceuticals","portco_name":"Xanodyne Pharmaceuticals","target_website":null,"investor":"MPM Capital","sponsor_is_investor":false,"sponsor_role":"co_investor","co_investors":["Apax Partners","Perseus-Soros BioPharmaceutical Fund","AIG Global Investment Group","Healthcare Ventures","Essex Woodlands","Blue Chip Venture Company","Coleman Swenson Hoffman Booth"],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Xanodyne Pharmaceuticals, backed by MPM Capital-led syndicate, approved to acquire pain management portfolio","summary":"Xanodyne Pharmaceuticals was financed by an equity syndicate led by MPM Capital and co-led by Apax Partners, with new and existing investors, to fund its purchase of aaiPharma's assets; the equity amount was not stated.","source_name":"Apax","source_url":"https://www.apax.com/news-views/xanodyne-pharmaceuticals-backed-by-mpm-capital-led-syndicate-approved-to-acquire-pain-management-portfolio/","evidence":"Xanodyne, a private company financed by an equity syndicate led by MPM Capital, and co-led by Apax Partners, headquartered in Greater Cincinnati, is dedicated to providing patient care in women's health and pain management. Other new investors included Perseus-Soros BioPharmaceutical Fund and affiliates of AIG Global Investment Group, while Silver Point Finance provided Xanodyne a term debt and revolver facility.","verified":null},{"key":"pr:d3e6bacfd41ceb10e5f30101ba2ff81a","date":"2005-07-18","date_text":null,"kind":"add_on_acquisition","asset_class":"private_equity","target":"aaiPharma (pharmaceutical assets)","portco_name":null,"target_website":null,"investor":"Xanodyne Pharmaceuticals","sponsor_is_inves